 private WebResourceResponse assetResponse(Uri uri){try{if(!allowed(uri))return resourceError(403,"Blocked");String path=uri.getPath();if(path==null||path.equals("/"))path="/index.html";if(path.contains("..")||path.contains("\\")||path.contains("\u0000"))return resourceError(404,"Not found");String mime=path.endsWith(".html")?"text/html":path.endsWith(".js")||path.endsWith(".mjs")?"text/javascript":path.endsWith(".css")?"text/css":path.endsWith(".svg")?"image/svg+xml":"application/octet-stream";Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-cache");headers.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,getAssets().open("dashboard"+path));}catch(Exception e){return resourceError(404,"Not found");}}
 private WebResourceResponse thumbnailResponse(String url){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);if(c.getResponseCode()!=200||c.getContentLengthLong()>1000000)return resourceError(404,"Thumbnail unavailable");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1000000)return resourceError(413,"Thumbnail too large");}return new WebResourceResponse("image/jpeg",null,new ByteArrayInputStream(out.toByteArray()));}}catch(Exception e){return resourceError(404,"Thumbnail unavailable");}finally{if(c!=null)c.disconnect();}}
