 private boolean handleTimerIntent(Intent intent){String id=intent.getStringExtra("timer_session");if(id==null)return false;StudyTimerState state=StudyTimerStore.read(this);if(state==null||!state.id.equals(id))return false;if(intent.getBooleanExtra("timer_finish",false)){StudyTimerService.pause(this,id);getSystemService(NotificationManager.class).cancel(StudyTimerService.NOTIFICATION_ID);}pendingTimerOpen=true;return true;}
 private void timerAction(String requestId,JSONObject data,boolean permissionHandled){try{String action=data.getString("action");if(!Arrays.asList("start","pause","resume","clear").contains(action))throw new Exception("Unknown timer action");String timerId=data.optString("id");StudyTimerState state=StudyTimerStore.read(this);if((action.equals("start")||action.equals("resume"))&&!resumed&&!permissionHandled)throw new Exception("Open Learning Space before starting a focus timer.");if(action.equals("start")&&state!=null&&!state.id.equals(timerId))throw new Exception("Finish or discard your current session first.");
 if((action.equals("start")||action.equals("resume"))&&!permissionHandled&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED&&!getSharedPreferences("focus_timer",0).getBoolean("permissionAsked",false)){timerPermissionId=requestId;timerPermissionData=data;getSharedPreferences("focus_timer",0).edit().putBoolean("permissionAsked",true).apply();requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},42);return;}
 if(action.equals("start")||action.equals("resume")){state=action.equals("start")?StudyTimerStore.start(this,data):StudyTimerStore.change(this,timerId,"resume");try{startForegroundService(new Intent(this,StudyTimerService.class).setAction("start").putExtra("timer_session",state.id));}catch(Exception e){StudyTimerStore.change(this,state.id,"pause");throw new Exception("Android could not start the background timer. Keep the app open and try again.");}}else if(action.equals("pause")){if(state==null||!state.id.equals(timerId))throw new Exception("This timer changed. Open your current session.");StudyTimerService.pause(this,timerId);}else StudyTimerService.clear(this,timerId);reply(requestId,200,timerPacket());
 }catch(Exception e){reply(requestId,400,error(e.getMessage()==null?"Could not update the timer.":e.getMessage()));}}
