 private byte[] progressImage(String png)throws Exception{if(png==null||!png.startsWith("data:image/png;base64,")||png.length()>3000000)throw new IOException("Invalid progress image");byte[] bytes=android.util.Base64.decode(png.substring(22),android.util.Base64.DEFAULT);android.graphics.BitmapFactory.Options opt=new android.graphics.BitmapFactory.Options();opt.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(opt.outWidth!=1080||opt.outHeight!=1350)throw new IOException("Invalid progress image");return bytes;}
