 private void request(String id,String url,String method,String body,String token,boolean openai)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(openai?45000:10000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+token);connection.setRequestProperty("Content-Type","application/json");try{if(method.equals("POST")||method.equals("PUT")){connection.setDoOutput(true);try(OutputStream out=connection.getOutputStream()){out.write((body==null?"":body).getBytes("UTF-8"));}}int status=connection.getResponseCode();if(status>=300&&openai){reply(id,502,error("OpenAI rejected the request. Check the key, model, permissions, and account quota."));return;}InputStream stream=status>=400?connection.getErrorStream():connection.getInputStream();String response=readBounded(stream,openai?500000:4000000);if(openai&&method.equals("GET")&&status==200)response="{\"valid\":true,\"message\":\"Connection verified without generating a model response.\"}";reply(id,status,response);}finally{connection.disconnect();}}
 private String readBounded(InputStream in,int max)throws Exception{if(in==null)return "{}";try(InputStream stream=in;ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=stream.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>max)throw new IOException("Response too large");}return bytes.toString("UTF-8");}}
 private void reply(String id,int status,String body){if(id==null||!id.matches("[a-zA-Z0-9-]{1,100}"))return;handler.post(()->{if(!trustedPage)return;try{JSONObject detail=new JSONObject().put("id",id).put("status",status).put("body",body);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('learning-native-response',{detail:"+detail.toString()+"}))",null);}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==21&&fileCallback!=null){pickedBook=null;pickedName="";if(result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();try(Cursor cursor=getContentResolver().query(uri,new String[]{"_display_name"},null,null,null)){if(cursor!=null&&cursor.moveToFirst())pickedName=cursor.getString(0);}if(pickedName.toLowerCase().matches(".*\\.(pdf|epub)$"))pickedBook=uri;fileCallback.onReceiveValue(new Uri[]{uri});}else fileCallback.onReceiveValue(null);fileCallback=null;}if(req==32&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(InputStream in=new FileInputStream(new File(getCacheDir(),"progress-export.png"));OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"Progress card saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save the image. Try another location.",Toast.LENGTH_LONG).show();}}if(req==22&&result==RESULT_OK&&data!=null)importUri(data.getData());if(req==31&&result==RESULT_OK&&data!=null){try(InputStream in=new FileInputStream(new File(getCacheDir(),"pending-export.json"));OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"Backup saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not export. Try another location.",Toast.LENGTH_LONG).show();}}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(!importIntent(intent)){if(handleTimerIntent(intent)){if(trustedPage)dispatchTimerOpen();else loadLocal("?page=today");}else loadLocal(safePath(intent.getStringExtra("path")));}}
 private boolean importIntent(Intent intent){if(Intent.ACTION_SEND.equals(intent.getAction())&&"text/plain".equals(intent.getType())){CharSequence value=intent.getCharSequenceExtra(Intent.EXTRA_TEXT);if(value!=null&&!value.toString().trim().isEmpty()){try{String id=intent.getStringExtra("learningShareId");if(id==null){id=UUID.randomUUID().toString();intent.putExtra("learningShareId",id);}String subject=intent.getStringExtra(Intent.EXTRA_SUBJECT);String text=value.toString();if(subject!=null&&!subject.isEmpty()&&!text.startsWith(subject))text=subject+"\n"+text;ShareDrafts.add(shareDraftFile(),id,text);if(trustedPage)web.evaluateJavascript("window.dispatchEvent(new Event('learning-native-share'))",null);else if(web.getUrl()==null)loadLocal("?page=inbox");}catch(Exception e){Toast.makeText(this,"Could not keep this shared draft. Save existing drafts or try pasting the link.",Toast.LENGTH_LONG).show();}return true;}}Uri u=null;if(Intent.ACTION_SEND.equals(intent.getAction()))u=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null){importUri(u);loadLocal("");return true;}return false;}
 private void importUri(Uri uri){try{String value=readBounded(getContentResolver().openInputStream(uri),4000000);JSONObject parsed=new JSONObject(value);if(parsed.has("resources")&&parsed.getInt("version")==1){try(FileOutputStream out=new FileOutputStream(new File(getCacheDir(),"pending-backup.json"))){out.write(value.getBytes("UTF-8"));}loadLocal("?page=settings");}else{WidgetStore.save(this,value);LearningWidget.updateAll(this);Toast.makeText(this,"Widgets updated",Toast.LENGTH_SHORT).show();}}catch(Exception e){new AlertDialog.Builder(this).setTitle("Choose a library backup or widget snapshot").setMessage("Course JSON imports use Add to library → File inside the dashboard.").setPositiveButton("OK",null).show();}}
 private void showWidgets(){String[] names={"Learning overview · 4×2","Today’s plan · 4×2","Streak · 3×2","Daily goal · 2×1","Next lesson · 4×1","Reading · 2×2","Weekly rhythm · 4×2","Refresh from the local app","Open hosted dashboard in browser"};new AlertDialog.Builder(this).setTitle("Your learning, at a glance").setItems(names,(d,which)->{if(which<7){Class<?>[] types={OverviewWidget.class,TodayWidget.class,StreakWidget.class,GoalWidget.class,NextWidget.class,ReadingWidget.class,WeekWidget.class};android.appwidget.AppWidgetManager m=android.appwidget.AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,types[which]),null,null);else Toast.makeText(this,"Long press home screen → Widgets → Learning Space",Toast.LENGTH_LONG).show();}else if(which==7)loadLocal("?page=today");else startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(ORIGIN)));}).show();}
