 @Override public void onBackPressed(){web.evaluateJavascript("!!document.querySelector('[role=dialog]')",value->{if("true".equals(value))web.evaluateJavascript("document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))",null);else web.evaluateJavascript("!window.dispatchEvent(new Event('learning-native-back',{cancelable:true}))",handled->{if(!"true".equals(handled)){if(web.canGoBack())web.goBack();else MainActivity.super.onBackPressed();}});});}
 @Override protected void onDestroy(){trustedPage=false;if(fileCallback!=null)fileCallback.onReceiveValue(null);network.shutdownNow();web.removeJavascriptInterface("LearningSpaceNative");web.destroy();super.onDestroy();}
